"""Render a portable, network-free geographic plot and quality report from the audit JSON."""
import argparse,json
from pathlib import Path

def render(directory):
    data=json.loads((directory/'plot-data.json').read_text())
    template='''<!doctype html><html><head><meta charset="utf-8"><title>DART trial quality review</title><style>
body{font-family:var(--font-sans,system-ui);color:var(--foreground,#ddd);margin:0}h1{font-size:23px}h2{font-size:18px;margin-top:26px}p,li{line-height:1.5}small,.note{color:var(--muted-foreground,#999);font-size:12px}svg{width:100%;display:block}text{fill:currentColor;font-family:inherit;font-size:11px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.stat{border-bottom:1px solid var(--border,#555);padding:10px 0}.stat b{font-size:22px;display:block}button,select{background:var(--secondary,#333);color:inherit;border:1px solid var(--border,#777);padding:7px;border-radius:5px}table{width:100%;font-size:12px;border-collapse:collapse}td,th{text-align:left;padding:6px;border-bottom:1px solid var(--border,#555)}.warning{border-left:3px solid var(--warning,#ca6);padding-left:14px} @media(max-width:520px){.grid{grid-template-columns:1fr}}</style></head><body>
<h1>DART trial: useful stop histories, station-level positions</h1>
<p class="note">Irish Rail archived API responses · 17 Nov 2026 18:09 to 18 Nov 2026 18:09 · Europe/Dublin (UTC). Service counts refer to train code plus service date, not individual trainsets.</p>
<div class="grid" id="stats"></div>
<h2>Geographic map of recorded positions</h2><p>All 19,087 scoped position observations use 32 station coordinates. Circle area reflects repeated observations, not passenger numbers or unique trains. Hover for counts.</p><label>Map display <select id="mode"><option value="positions">Position observation counts</option><option value="coverage">Intermediate-stop arrival availability</option></select></label><div id="map"></div><p id="mapnote" class="note"></p>
<h2>Data-quality findings</h2><div class="warning"><ul>
<li><b>Undocumented service state:</b> E111, Howth–Greystones on 18 November, is excluded because all 35 latest locations have LocationType=C. The API documentation does not define that value. Preserve the service as an unresolved state rather than discarding it or assuming cancellation.</li>
<li><b>Station type anomaly:</b> Dublin Pearse has 102 latest corridor-service records marked T (timing point), despite being a passenger station. The S-only statistics below omit these. For those services, 284 archived Pearse station-board observations instead label the location S. Do not interpret these as skipped stops.</li>
<li><b>Times are mostly automatically generated:</b> 5,573 of 5,582 valid passenger-stop arrival values have AutoArrival=1. Treat delays as feed-reported estimates, not independently measured ground truth.</li>
<li><b>No continuous GPS or measured speed:</b> all positions are station coordinates; 72.4% of consecutive position pairs for the same service are unchanged.</li>
</ul></div>
<h2>Reported arrival delay at buffered intermediate stops</h2><div id="delays"></div><p id="delaynote" class="note"></p>
<h2>Position observations by hour</h2><div id="hourly"></div><p class="note">Count of individual train observations, not requests or unique services. First and last hours are partial. Overnight service gaps do not mean the collector stopped. Source: scoped position observations, full trial.</p>
<h2>Observed service routes</h2><div id="routes"></div><p class="note">231 included service-date identities; a service can have incomplete coverage at the trial boundaries. Includes short workings. E111 excluded from this table. No independent timetable completeness denominator.</p>
<h2>Stop-time coverage by station</h2><p id="coverage"></p><div style="overflow:auto"><table><thead><tr><th>Station</th><th>Latest passenger stops</th><th>Buffered intermediate stops</th><th>Arrival available</th><th>Departure available</th></tr></thead><tbody id="stations"></tbody></table></div><p class="note">Arrival/departure percentages use intermediate S locations scheduled between 17 Nov 18:39 and 18 Nov 17:39. Origin/destination and 00:00:00 sentinel values are excluded. A midnight event would require independent disambiguation. Time subtraction wraps to ±12 hours; extreme delays need manual validation. This is an exploratory sample, not a published punctuality metric.</p>
<h2>Terminal-event availability</h2><p id="terminal"></p><h2>Collection integrity and next steps</h2><p id="integrity"></p><ol><li>Retain unresolved and cancelled services separately from verified corridor services; validate LocationType=C and Pearse timing points.</li><li>Version a timetable and compare scheduled service identities to observations. Separate genuine omissions from cancellations and boundary truncation.</li><li>Keep raw XML, automatic-time flags and both scheduled and expected times. Use date-aware events and an end-of-run tail to capture final arrivals.</li><li>Then deploy continuous AWS collection with storage backups and alerts based on successful response age.</li></ol>
<script>const D=__DATA__,m=D.metrics;const fmt=n=>n.toLocaleString('en-IE'),pct=(a,b)=>b?(100*a/b).toFixed(1)+'%':'not applicable';
document.querySelector('#stats').innerHTML=[['231','included service-date identities'],[fmt(m.position_observations),'scoped position observations'],[pct(m.buffered_arrivals,m.buffered_intermediate_stops),'buffered intermediate arrivals available'],[m.max_successful_position_gap_seconds.toFixed(0)+' seconds','longest gap between successful position responses']].map(([a,b])=>`<div class="stat"><b>${a}</b>${b}</div>`).join('');
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const stations=Object.fromEntries(m.stations.map(s=>[s.code,s]));
function map(){const mode=document.querySelector('#mode').value,W=690,H=700; const x=lon=>65+(lon+6.30)*1500,y=lat=>35+(53.47-lat)*1050/Math.cos(53.3*Math.PI/180);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Geographic DART station map, longitude and latitude in degrees">`;
for(let lat=53.15;lat<=53.45;lat+=.05){svg+=`<path d="M50 ${y(lat)}H650" stroke="var(--border,#444)"/><text x="2" y="${y(lat)+4}">${lat.toFixed(2)}°N</text>`;}
for(let lon=-6.25;lon<=-6.05;lon+=.05){svg+=`<text x="${x(lon)}" y="680">${Math.abs(lon).toFixed(2)}°W</text>`;}
const branches=['MHIDE PMNCK GRGRD HWTHJ','HOWTH SUTTN BYSDE HWTHJ','HWTHJ KBRCK RAHNY HTOWN KLSTR CTARF CNLLY TARA PERSE GCDK LDWNE SMONT SIDNY BTSTN BROCK SEAPT SHILL DLERY SCOVE GLGRY DLKEY KILNY SKILL WBROK BRAY GSTNS'];
branches.forEach(b=>{svg+=`<polyline fill="none" stroke="var(--muted-foreground,#888)" stroke-width="2" points="${b.split(' ').map(c=>`${x(stations[c].lon)},${y(stations[c].lat)}`).join(' ')}"/>`;});
m.stations.forEach(s=>{const point=D.points.find(p=>Math.abs(p.lat-s.lat)<.00001&&Math.abs(p.lon-s.lon)<.00001),n=point?point.n:0; const r=mode==='positions'?3+Math.sqrt(n)/4:6;const fill=mode==='positions'?'var(--chart-1,#77bbaa)':!s.eligible?'var(--muted,#777)':s.arrivals/s.eligible>=.98?'var(--success,#6a8)':'var(--warning,#ca6)';svg+=`<circle cx="${x(s.lon)}" cy="${y(s.lat)}" r="${r}" fill="${fill}" fill-opacity=".7"><title>${esc(s.name)}: ${n} position observations; buffered arrivals ${s.arrivals||0}/${s.eligible||0}</title></circle>`;
if(['MHIDE','HOWTH','HWTHJ','CNLLY','PERSE','DLERY','BRAY','GSTNS','WBROK'].includes(s.code)){let dx=s.code==='PERSE'?-95:14;svg+=`<text x="${x(s.lon)+dx}" y="${y(s.lat)+(s.code==='HWTHJ'?18:4)}">${esc(s.name)}</text>`;}});
svg+='</svg>';document.querySelector('#map').innerHTML=svg;document.querySelector('#mapnote').textContent=mode==='positions'?'Latitude/longitude plot using a local equirectangular projection. North is up. Lines connect stations schematically; they are not surveyed track geometry. No basemap or external network dependency. Source: station metadata and scoped positions, full trial.':'Green: at least 98% of eligible arrivals present; amber: below 98%; grey: no eligible intermediate-stop sample. Origin/destination stations are not assessed in this metric. Source: latest scoped movements, buffered sample.';}
map();document.querySelector('#mode').onchange=map;
function bars(id,items,max,axis){const H=items.length*27+45;document.querySelector(id).innerHTML=`<svg viewBox="0 0 690 ${H}" role="img" aria-label="${axis}">${items.map(([label,n],i)=>`<text x="0" y="${i*27+16}">${esc(label)}</text><rect x="240" y="${i*27+3}" width="${n/max*390}" height="17" fill="var(--chart-1,#77bbaa)"/><text x="${245+n/max*390}" y="${i*27+16}">${fmt(n)}</text>`).join('')}<text x="240" y="${H-4}">${axis}; scale 0–${max}</text></svg>`;}
bars('#delays',['early (<-1)','within -1 to +5','5 to 10 late','>10 late'].map(k=>[k+' min',m.delay_buckets[k]||0]),3000,'Arrival delay bucket → stop records');
document.querySelector('#delaynote').textContent=`Source: ${fmt(m.reported_arrival_delay_minutes.n)} latest available arrivals at buffered intermediate stops. Median ${m.reported_arrival_delay_minutes.median.toFixed(1)} min late; 95th percentile ${m.reported_arrival_delay_minutes.p95.toFixed(1)} min. Stop-weighted, correlated within journeys; mostly automatically generated times. Pearse T records omitted. These are not network-wide punctuality estimates.`;
bars('#hourly',Object.entries(m.hourly_position_observations),Math.ceil(Math.max(...Object.values(m.hourly_position_observations))/500)*500,'UTC hour → train position observations');
bars('#routes',m.routes.map(r=>[r.origin+' → '+r.destination,r.services]),40,'Origin → destination; service-date count');
document.querySelector('#coverage').textContent=`${fmt(m.buffered_arrivals)} of ${fmt(m.buffered_intermediate_stops)} eligible arrivals (${pct(m.buffered_arrivals,m.buffered_intermediate_stops)}); ${fmt(m.buffered_departures)} departures (${pct(m.buffered_departures,m.buffered_intermediate_stops)}). All 32 requested stations occur in the archive. Eleven included services had no positions; all were scheduled to start after the trial cutoff.`;
document.querySelector('#stations').innerHTML=m.stations.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.stops||0}</td><td>${s.eligible||0}</td><td>${s.arrivals||0} (${pct(s.arrivals||0,s.eligible||0)})</td><td>${s.departures||0} (${pct(s.departures||0,s.eligible||0)})</td></tr>`).join('');
const t=m.terminal_time_coverage;document.querySelector('#terminal').textContent=`Within the same 30-minute boundary buffer, ${t.D_available}/${t.D_eligible} destination arrivals (${pct(t.D_available,t.D_eligible)}) and ${t.O_available}/${t.O_eligible} origin departures (${pct(t.O_available,t.O_eligible)}) are available. These are service endpoints across the corridor, including short workings. Missing intermediate arrivals cluster in ${Object.keys(m.missing_arrivals_by_service).length} service-date identities; E950 on 17 Nov accounts for 18 and E923 on 18 Nov for 17. Investigate these journeys before computing detailed reliability metrics.`;
document.querySelector('#integrity').textContent=`SQLite integrity: ${m.sqlite_integrity}. All ${fmt(m.archive.checked)} stored response bodies decompressed and matched their recorded SHA-256 hashes; none missing. ${m.failures} requests failed out of ${fmt(m.requests)} (${(100*m.failures/m.requests).toFixed(3)}%): 14 timeouts and 2 connection refusals. Failed requests are logged with no stored response body. The earlier 77-second maximum measured attempts, not successful responses; the successful-response gap is ${m.max_successful_position_gap_seconds.toFixed(0)} seconds. No independent timetable completeness check has been performed.`;
</script></body></html>'''
    (directory/'review.html').write_text(template.replace('__DATA__',json.dumps(data).replace('</','<\\/')))
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('directory',type=Path);render(p.parse_args().directory)
